  if (le) {
    const [, col, hi] = le;
    const before = q.slice(0, le.index).trimEnd();
    if (!/(date|strftime|substr)\s*\($/i.test(before)) {
      return `${col} <= '${hi}' compares text: '${hi}T…' sorts after '${hi}', so rows later on ${hi} are dropped. Use ${col} < '${nextDay(hi)}'.`;
    }
  }
