/**
 * FeedbackPromptCard — capture points 2-4 (E2, 2026-11-22). One question,
 * skippable, never a modal: `exit_reason` (five taps, "Other" opens a line),
 * `stuck` and `day2` (one line). Rules live in src/utils/feedback-prompts.js.
 * Neutral surface colours only; the accent is never used here (DESIGN.md).
 */
function FeedbackPromptCard({ kind, onSend, onSkip, compact = false, answered = false }) {
  const [text, setText] = React.useState('');
  const [picked, setPicked] = React.useState(null);
  // `answered` comes from the prompt, not this card: a card re-mounted after a
  // Pro modal closes must open on the thanks, never on the question again.
  const [status, setStatus] = React.useState(answered ? 'done' : 'idle'); // idle | sending | done | error
  const tt = (k) => i18n_t('feedback', k);
  const btn = 'min-h-[44px] px-3 rounded-md text-sm transition';
  const neutral = { background: '#1F222B', border: '1px solid #2A2E38', color: '#F2F0EA' };
  const send = async (answerId, line) => {
    if (status === 'sending') return;
    setStatus('sending');
    const ok = await onSend(answerId, line);
    setStatus(ok ? 'done' : 'error');
  };
  const question = kind === 'exit_reason' ? tt('exitQ') : kind === 'stuck' ? tt('stuckPromptQ') : tt('day2Q');
  const placeholder = kind === 'exit_reason' ? tt('exitOtherPlaceholder') : kind === 'stuck' ? tt('stuckPromptPlaceholder') : tt('day2Placeholder');
  const showLine = kind !== 'exit_reason' || picked === 'other';
  if (status === 'done') {
    return (
      <div data-testid={`feedback-prompt-${kind}`} data-state="done" className={compact ? 'mt-3' : 'rounded-lg p-3'} style={compact ? undefined : { background: '#16181F', border: '1px solid #2A2E38' }}>
        <p className="text-sm" style={{ color: '#8A8E99' }}>{tt('promptThanks')}</p>
      </div>
    );
  }
  return (
    <div data-testid={`feedback-prompt-${kind}`} className={compact ? 'mt-3' : 'rounded-lg p-3'} style={compact ? undefined : { background: '#16181F', border: '1px solid #2A2E38' }}>
      <div className="flex items-start justify-between gap-2 mb-2">
        <p className="text-sm font-semibold" style={{ color: '#F2F0EA' }}>{question}</p>
        {!compact && (
          <button onClick={onSkip} className="min-h-[44px] min-w-[44px] -mt-3 -mr-2 text-sm shrink-0" style={{ color: '#8A8E99' }} data-testid="feedback-prompt-skip">{tt('promptSkip')}</button>
        )}
      </div>
      {kind === 'exit_reason' && (
        <div className="flex flex-wrap gap-2 mb-2">
          {EXIT_REASONS.map(r => (
            <button
              key={r.id}
              data-answer={r.id}
              disabled={status === 'sending'}
              onClick={() => { if (r.text) { setPicked('other'); } else { send(r.id, ''); } }}
              className={btn}
              style={picked === r.id ? { ...neutral, borderColor: '#8A8E99' } : neutral}
            >{tt(r.label)}</button>
          ))}
        </div>
      )}
      {showLine && (
        <form className="flex gap-2" onSubmit={(e) => { e.preventDefault(); const line = text.trim(); if (kind === 'exit_reason') send('other', line); else if (line) send(null, line); }}>
          <input
            value={text}
            onChange={(e) => setText(e.target.value)}
            maxLength={300}
            placeholder={placeholder}
            aria-label={question}
            className="flex-1 min-w-0 min-h-[44px] px-3 rounded-md text-sm"
            style={{ background: '#0E0F13', border: '1px solid #2A2E38', color: '#F2F0EA' }}
          />
          <button type="submit" disabled={status === 'sending' || (kind !== 'exit_reason' && !text.trim())} className={btn} style={neutral}>{tt('promptSend')}</button>
        </form>
      )}
      {status === 'error' && <p className="text-xs mt-2" style={{ color: '#FF6B6B' }}>{tt('error')}</p>}
    </div>
  );
}

function FeedbackWidget({ open, onOpen, onClose, onSubmit, onTopicPick, screen, initialTopic = null, tutorLine = false, onTutor = null }) {
  const [message, setMessage] = React.useState('');
  const [contact, setContact] = React.useState('');
  const [topic, setTopic] = React.useState(null);
  // Quote consent. Default OFF, always, and reset to OFF every time the
  // widget opens — a sticky checkbox would carry a consent from one message
  // to the next, which is exactly what "explicit and separate" forbids.
  const [quoteConsent, setQuoteConsent] = React.useState(false);
  const [quoteName, setQuoteName] = React.useState('');
  const [quoteConsentAt, setQuoteConsentAt] = React.useState(null);
  const [state, setState] = React.useState('idle'); // idle | sending | sent | error
  const taRef = React.useRef(null);

  React.useEffect(() => {
    if (open) {
      setState('idle');
      setTopic(initialTopic || null);
      setQuoteConsent(false);
      setQuoteName('');
      setQuoteConsentAt(null);
      // Focus the textarea, not the first focusable element — the user opened
      // this to type, not to tab through it.
      setTimeout(() => { try { taRef.current?.focus(); } catch (_) {} }, 60);
    }
  }, [open, initialTopic]);

  React.useEffect(() => {
    if (!open) return;
    const onKey = (e) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open, onClose]);

  if (!open) {
    return (
      <button
        onClick={onOpen}
        aria-label={i18n_t('feedback', 'openAria')}
        title={i18n_t('feedback', 'openAria')}
        className="sq-feedback-fab fixed bottom-4 right-4 z-40 w-11 h-11 rounded-full flex items-center justify-center text-lg shadow-lg transition hover:scale-105"
        style={{ background: '#16181F', border: '1px solid #2A2E38', color: '#F2F0EA' }}
      >
        💬
      </button>
    );
  }

  const send = async () => {
    const body = message.trim();
    if (!body || state === 'sending') return;
    setState('sending');
    const ok = await onSubmit({
      message: body,
      contact: contact.trim() || null,
      topic,
      // Only ever sent when the box is actually ticked. An unticked box sends
      // `false` and a NULL name/timestamp, never a partial consent.
      quoteConsent,
      quoteName: quoteConsent ? (quoteName.trim() || null) : null,
      quoteConsentAt: quoteConsent ? quoteConsentAt : null,
    });
    if (ok) {
      setState('sent');
      setMessage(''); setContact(''); setTopic(null);
      setQuoteConsent(false); setQuoteName(''); setQuoteConsentAt(null);
      setTimeout(onClose, 1600);
    } else {
      setState('error');
    }
  };

  // z-[10001] puts this above the first-run tour (9999) and the goal gate
  // (10000) — a feedback box the user deliberately opened should never
  // render underneath something else.
  return (
    <div
      className="fixed inset-0 z-[10001] flex items-end sm:items-center justify-center p-4"
      style={{ background: 'rgba(0,0,0,0.6)' }}
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
      role="dialog" aria-modal="true" aria-label={i18n_t('feedback', 'title')}
    >
      <div
        className="w-full max-w-md rounded-2xl p-5"
        style={{ background: '#16181F', border: '1px solid #2A2E38' }}
      >
        <div className="flex items-start justify-between gap-3 mb-1">
          <h3 className="text-lg font-bold" style={{ color: '#F2F0EA' }}>{i18n_t('feedback', 'title')}</h3>
          <button onClick={onClose} aria-label="Close" className="text-xl leading-none px-1" style={{ color: '#8A8E99' }}>×</button>
        </div>
        <p className="text-sm mb-4" style={{ color: '#8A8E99' }}>{i18n_t('feedback', 'subtitle')}</p>

        {state === 'sent' ? (
          <div className="py-6 text-center">
            <div className="text-3xl mb-2">✅</div>
            <p className="text-sm font-semibold" style={{ color: '#F2F0EA' }}>{i18n_t('feedback', 'thanks')}</p>
            <p className="text-xs mt-1" style={{ color: '#8A8E99' }}>{i18n_t('feedback', 'thanksBody')}</p>
          </div>
        ) : (
          <>
            {/* Surface, not accent: DESIGN.md reserves #FFE34D for the primary
                CTA, which is the Send button below. Selection reads through
                border + text weight instead. */}
            <div className="flex flex-wrap gap-2 mb-3">
              {FEEDBACK_TOPICS.filter(t => !t.hidden).map(t => {
                const active = topic === t.id;
                return (
                  <button
                    key={t.id}
                    onClick={() => {
                      setTopic(t.id);
                      try { onTopicPick && onTopicPick(t.id); } catch (_) {}
                      try { taRef.current?.focus(); } catch (_) {}
                    }}
                    className="px-3 py-1.5 rounded-lg text-xs transition"
                    style={{
                      background: active ? '#1F222B' : '#0E0F13',
                      border: `1px solid ${active ? '#8A8E99' : '#2A2E38'}`,
                      color: active ? '#F2F0EA' : '#8A8E99',
                      fontWeight: active ? 600 : 400,
                    }}
                  >
                    {i18n_t('feedback', t.label)}
                  </button>
                );
              })}
            </div>
            {/* IR-2 (flag feedbackContext): on a challenge, say where this box
                goes and where help is. Muted text, the link in body text —
                never the accent, which stays on Send (DESIGN.md). */}
            {tutorLine && onTutor && (
              <p className="text-xs mb-2" style={{ color: '#8A8E99' }} data-testid="feedback-tutor-line">
                {i18n_t('feedback', 'tutorLineBefore')}
                <button
                  type="button"
                  onClick={onTutor}
                  className="underline font-semibold"
                  style={{ color: '#F2F0EA' }}
                  data-testid="feedback-tutor-link"
                >{i18n_t('feedback', 'tutorLineLink')}</button>
                {i18n_t('feedback', 'tutorLineAfter')}
              </p>
            )}
            <textarea
              ref={taRef}
              value={message}
              onChange={(e) => setMessage(e.target.value.slice(0, 4000))}
              rows={5}
              placeholder={i18n_t('feedback', topic
                ? (FEEDBACK_TOPICS.find(t => t.id === topic) || {}).placeholder
                : 'placeholder')}
              className="w-full rounded-xl p-3 text-sm resize-none outline-none"
              style={{ background: '#0E0F13', border: '1px solid #2A2E38', color: '#F2F0EA' }}
            />
            <input
              type="email"
              value={contact}
              onChange={(e) => setContact(e.target.value.slice(0, 200))}
              placeholder={i18n_t('feedback', 'emailPlaceholder')}
              className="w-full rounded-xl p-3 text-sm mt-2 outline-none"
              style={{ background: '#0E0F13', border: '1px solid #2A2E38', color: '#F2F0EA' }}
            />
            {/* Quote consent — explicit, separate, default OFF.
                Nothing is offered in exchange for ticking this. It is not a
                condition of sending, it grants no XP, no Pro days and no
                badge, and the copy says plainly that nothing changes either
                way. An unstated material connection between a reviewer and a
                seller is what FTC 16 CFR Part 255 prohibits; the way not to
                have one is not to create one. See src/utils/review-ask.js.
                Surface colours only — the accent (#FFE34D) stays on the Send
                CTA below, per DESIGN.md's scarcity rule. */}
            <label
              className="flex items-start gap-2 mt-3 cursor-pointer select-none"
              data-testid="feedback-quote-consent"
            >
              <input
                type="checkbox"
                checked={quoteConsent}
                onChange={(e) => {
                  const on = e.target.checked;
                  setQuoteConsent(on);
                  // Stamp the moment of consent, not the moment of send.
                  // Cleared on untick so a withdrawn consent leaves nothing
                  // behind to be read as one.
                  setQuoteConsentAt(on ? new Date().toISOString() : null);
                  if (!on) setQuoteName('');
                }}
                className="mt-0.5 w-4 h-4 flex-shrink-0"
                style={{ accentColor: '#8A8E99' }}
              />
              <span className="min-w-0">
                <span className="block text-xs" style={{ color: '#F2F0EA' }}>{i18n_t('feedback', 'quoteConsent')}</span>
                <span className="block text-[11px] mt-0.5" style={{ color: '#8A8E99' }}>{i18n_t('feedback', 'quoteConsentHelp')}</span>
              </span>
            </label>
            {quoteConsent && (
              <input
                type="text"
                value={quoteName}
                onChange={(e) => setQuoteName(e.target.value.slice(0, 80))}
                placeholder={i18n_t('feedback', 'quoteNamePlaceholder')}
                className="w-full rounded-xl p-3 text-sm mt-2 outline-none"
                style={{ background: '#0E0F13', border: '1px solid #2A2E38', color: '#F2F0EA' }}
              />
            )}
            {state === 'error' && (
              <p className="text-xs mt-2" style={{ color: '#FF6B6B' }}>{i18n_t('feedback', 'error')}</p>
            )}
            <div className="flex items-center justify-between gap-3 mt-4">
              <span className="text-xs" style={{ color: '#8A8E99' }}>{message.length}/4000</span>
              <button
                onClick={send}
                disabled={!message.trim() || state === 'sending'}
                className="px-5 py-2.5 rounded-xl font-bold text-sm transition disabled:opacity-40"
                style={{ background: '#FFE34D', color: '#0E0F13' }}
              >
                {state === 'sending' ? i18n_t('feedback', 'sending') : i18n_t('feedback', 'send')}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

/**
 * ReviewAskCard — the one time we ask a user to say something in public.
 *
 * A CARD, NOT A MODAL, and that is a measurement decision as much as a
 * courtesy one: it renders inline in the post-solve success panel, blocks
 * nothing, and steals no click from the "what's next" buttons beneath it. An
 * interrupting dialog here would sit on top of the surface the open
 * paywall-surfaces ledger claim is reading until 2026-09-20 and would confound
 * it — as well as annoying the one person in a hundred who might have written
 * something.
 *
 * WHAT THIS COMPONENT DELIBERATELY DOES NOT DO:
 *   - It offers nothing in return. No discount, no XP, no Pro days, no badge,
 *     no streak credit. FTC 16 CFR Part 255 and every review platform's terms
 *     forbid incentivised reviews, and at our size one flagged listing is
 *     unrecoverable. `tests/review-ask.test.js` fails the build if an
 *     incentive word appears near this copy.
 *   - It does not suggest what to write. No star preset, no draft, no "mention
 *     the Coach". The link, not the words.
 *   - It does not ask for a rating first and route by sentiment. Filtering
 *     unhappy users toward the private channel and happy ones toward the
 *     public one is review gating, which Trustpilot and Google both treat as
 *     manipulation. Both doors are offered to everybody, side by side.
 *
 * Pure presentational: eligibility, storage and analytics all live in the
 * parent (`shouldAskForReview` in src/utils/review-ask.js decides).
 */
function ReviewAskCard({ solves, platform, onShown, onReview, onPrivateNote, onCopyLink, onDismiss }) {
  // "Shown" is emitted on mount, not on the parent's decision, so the event
  // and the once-ever flag can never disagree: if this component is on screen,
  // the ask happened; if it never mounted, it did not. Empty dep array — one
  // mount, one event, whatever re-renders the success panel does afterwards.
  React.useEffect(() => {
    if (!platform) return;
    try { onShown && onShown(); } catch (_) {}
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  if (!platform) return null;
  return (
    <div
      className="mb-3 p-3 rounded-lg"
      data-testid="review-ask-card"
      style={{ background: '#1F222B', border: '1px solid #2A2E38' }}
    >
      <div className="flex items-start justify-between gap-3">
        <p className="text-sm font-bold" style={{ color: '#F2F0EA' }}>{i18n_t('review', 'title')}</p>
        <button
          onClick={onDismiss}
          aria-label={i18n_t('review', 'dismissAria')}
          title={i18n_t('review', 'dismissAria')}
          className="flex-shrink-0 text-xs leading-none px-1 py-0.5"
          style={{ color: '#8A8E99' }}
        >✕</button>
      </div>
      {/* The only pre-filled fact anywhere in this flow: the user's own solve
          count. A statement about them, never an opinion about us. */}
      <p className="text-xs mt-1.5" style={{ color: '#8A8E99' }}>
        {i18n_t('review', 'body', { n: solves })}
      </p>
      {/* Said plainly, because it is the thing that makes the ask fair: the
          review is not visible to us as theirs, and refusing costs nothing. */}
      <p className="text-[11px] mt-1.5" style={{ color: '#8A8E99' }}>
        {i18n_t('review', 'privacy')}
      </p>
      <div className="flex flex-wrap items-center gap-2 mt-3">
        {/* Primary CTA, so it carries the accent — DESIGN.md allows #FFE34D on
            primary CTAs and nowhere else on this card. */}
        <a
          href={platform.url}
          target="_blank"
          rel="noopener noreferrer nofollow"
          onClick={() => onReview(platform)}
          data-testid="review-ask-cta"
          className="px-4 py-2 rounded-lg font-bold text-xs transition"
          style={{ background: '#FFE34D', color: '#0E0F13' }}
        >
          {i18n_t('review', 'cta')}
        </a>
        <button
          onClick={onPrivateNote}
          className="px-3 py-2 rounded-lg font-medium text-xs transition"
          style={{ background: '#0E0F13', border: '1px solid #2A2E38', color: '#8A8E99' }}
        >
          {i18n_t('review', 'privateNote')}
        </button>
        {/* The profile share link, surfaced HERE because its only other home
            is the archetype banner on Profile → Skills, and that banner has
            produced zero interactions of any kind in production: 0
            profile_link_copied, 0 profile_opened, and 0 of the 14
            radar_png_copied rows (all 14 came from the post-solve radar
            toast, surface='radar_pop', 8 people, 08-07..09-03). The button
            was not ignored — it was never reached. */}
        {onCopyLink && (
          <button
            onClick={onCopyLink}
            data-testid="review-ask-copy-link"
            className="px-3 py-2 rounded-lg font-medium text-xs transition"
            style={{ background: '#0E0F13', border: '1px solid #2A2E38', color: '#8A8E99' }}
          >
            🔗 {i18n_t('review', 'copyLink')}
          </button>
        )}
      </div>
    </div>
  );
}

/**
 * InterviewPrepCard — name a company, name a date, see where you are and what
 * to do today.
 *
 * SHIPPED OFF: the parent renders this only when
 * `window.FF?.feature?.('interviewCountdown') === true`, which is false in
 * src/data/feature-flags.js until after the paywall-surfaces read on
 * 2026-09-20. It sits at the top of the Interview Prep tab, above the header
 * panel, and it changes what that tab sends people into for the same
 * population that claim is measuring. One surface, one change at a time
 * (docs/data-driven-product.md P7).
 *
 * A CARD, not a modal — nothing here interrupts anybody, and there is no
 * `fixed inset-0` or `role="dialog"` in this component by design.
 *
 * All logic lives in src/utils/interview-prep.js; this renders what it is
 * handed. The one rule this component itself carries: **the score is always
 * rendered next to what it was measured from**. `whatItIs` and `notAffiliated`
 * are not optional decoration and must not be collapsed behind a tooltip — a
 * bare "73 / 100" beside a company's name reads as a prediction, and it is not
 * one.
 *
 * Colours are DESIGN.md tokens inline, the same posture as ReviewAskCard. The
 * accent #FFE34D appears on exactly one element, the score value, which is a
 * score/XP value — the one place DESIGN.md permits it on this card.
 */
function InterviewPrepCard({
  targets, target, dateValue, readiness, plan, minEvidenceSolves, minTagged, mockMinutes,
  onTargetChange, onDateChange, onClear, onOpenItem, onShown,
}) {
  // One impression event per mount, like ReviewAskCard: if this is on screen
  // the readiness was shown, and the bucket is what the funnel reads.
  React.useEffect(() => {
    try { onShown && onShown(); } catch (_) {}
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (!Array.isArray(targets) || targets.length === 0) return null;

  // Two tiers in one picker (2026-09-17): the signed archetypes first — a
  // number and a timed mock — then every company with enough tagged
  // questions for a plan, by count. A tagged target renders the note where
  // the score would be, and never a score.
  const signedTargets = targets.filter(t => t && t.kind !== 'tagged');
  const taggedTargetsList = targets.filter(t => t && t.kind === 'tagged');
  const isTagged = target?.kind === 'tagged';

  const company = target?.company || null;
  const status = plan?.status || null;
  const days = plan?.daysRemaining;
  const countdown = days == null
    ? null
    : (days === 0
        ? i18n_t('interviewPrep', 'daysToGoToday')
        : days === 1
          ? i18n_t('interviewPrep', 'daysToGoOne')
          : i18n_t('interviewPrep', 'daysToGo', { n: days }));

  const itemLabel = (item) => {
    if (item.kind === 'mock') return i18n_t('interviewPrep', 'itemMock', { n: mockMinutes });
    if (item.kind === 'drill') return i18n_t('interviewPrep', 'itemDrill', { skill: item.skill });
    return i18n_t('interviewPrep', 'itemTarget', { company });
  };

  const Part = ({ label, value, weight, note }) => (
    <div className="flex items-baseline justify-between gap-3 py-1">
      <span className="text-xs" style={{ color: '#8A8E99' }}>{label}</span>
      <span className="text-xs tabular-nums" style={{ color: '#F2F0EA' }}>
        {value}
        <span style={{ color: '#8A8E99' }}>
          {' · '}{note || i18n_t('interviewPrep', 'partWeight', { pct: Math.round((weight || 0) * 100) })}
        </span>
      </span>
    </div>
  );

  return (
    <div
      data-testid="interview-prep-card"
      className="p-5 rounded-xl"
      style={{ background: '#16181F', border: '1px solid #2A2E38' }}
    >
      <p className="text-base font-bold" style={{ color: '#F2F0EA' }}>
        🎯 {i18n_t('interviewPrep', 'title')}
      </p>
      <p className="text-xs mt-1" style={{ color: '#8A8E99' }}>
        {i18n_t('interviewPrep', 'subtitle')}
      </p>

      {/* ── the two inputs ── */}
      <div className="flex flex-wrap items-end gap-3 mt-4">
        <label className="flex flex-col gap-1">
          <span className="text-[11px]" style={{ color: '#8A8E99' }}>
            {i18n_t('interviewPrep', 'targetLabel')}
          </span>
          <select
            data-testid="interview-prep-target"
            value={company || ''}
            onChange={(e) => onTargetChange(e.target.value || null)}
            className="px-3 py-2 rounded-lg text-sm"
            style={{ background: '#0E0F13', border: '1px solid #2A2E38', color: '#F2F0EA' }}
          >
            <option value="">{i18n_t('interviewPrep', 'targetPlaceholder')}</option>
            {signedTargets.length > 0 && (
              <optgroup label={i18n_t('interviewPrep', 'groupSigned')}>
                {signedTargets.map(t => <option key={t.company} value={t.company}>{t.company}</option>)}
              </optgroup>
            )}
            {taggedTargetsList.length > 0 && (
              <optgroup label={i18n_t('interviewPrep', 'groupTagged')}>
                {taggedTargetsList.map(t => <option key={t.company} value={t.company}>{t.company} · {t.challengeCount}</option>)}
              </optgroup>
            )}
          </select>
        </label>
        <label className="flex flex-col gap-1">
          <span className="text-[11px]" style={{ color: '#8A8E99' }}>
            {i18n_t('interviewPrep', 'dateLabel')}
          </span>
          <input
            type="date"
            data-testid="interview-prep-date"
            value={dateValue || ''}
            onChange={(e) => onDateChange(e.target.value || null)}
            className="px-3 py-2 rounded-lg text-sm tabular-nums"
            style={{ background: '#0E0F13', border: '1px solid #2A2E38', color: '#F2F0EA' }}
          />
        </label>
        {(company || dateValue) && (
          <button
            onClick={onClear}
            className="px-3 py-2 rounded-lg text-xs"
            style={{ background: '#0E0F13', border: '1px solid #2A2E38', color: '#8A8E99' }}
          >
            {i18n_t('interviewPrep', 'clear')}
          </button>
        )}
        {countdown && (
          <span className="text-xs pb-2 tabular-nums" style={{ color: '#8A8E99' }}>{countdown}</span>
        )}
      </div>

      {/* Why the picker is one item long. Stated on the surface rather than in
          a comment, because a user looking for their own employer deserves the
          reason rather than an empty list. */}
      <p className="text-[11px] mt-2" style={{ color: '#8A8E99' }}>
        {i18n_t('interviewPrep', 'onlyTargets', { n: minTagged })}
      </p>

      {company && (
        <div className="mt-4 pt-4" style={{ borderTop: '1px solid #2A2E38' }}>
          {/* ── the number, and immediately under it what it is ── */}
          {isTagged ? (
            // A tagged target: the plan and the note, no score. The note is
            // the same sentence interview-prep.js taggedTargetNote() carries.
            <p data-testid="interview-prep-tagged-note" className="text-[11px]" style={{ color: '#8A8E99' }}>
              {i18n_t('interviewPrep', 'taggedNote', { company, n: target.challengeCount })}
            </p>
          ) : readiness ? (
            <>
              <div className="flex items-baseline gap-2">
                <span className="text-xs" style={{ color: '#8A8E99' }}>
                  {i18n_t('interviewPrep', 'readinessTitle')}
                </span>
                <span
                  data-testid="interview-prep-score"
                  className="text-2xl font-bold tabular-nums"
                  style={{ color: '#FFE34D' }}
                >
                  {readiness.score}
                </span>
                <span className="text-xs" style={{ color: '#8A8E99' }}>/ 100</span>
              </div>
              <p className="text-[11px] mt-1.5" style={{ color: '#8A8E99' }}>
                {i18n_t('interviewPrep', 'whatItIs', { company, n: readiness.parts.coverage.total })}
              </p>
              <p className="text-[11px] mt-1" style={{ color: '#8A8E99' }}>
                {i18n_t('interviewPrep', 'notAffiliated', { company })}
              </p>
              <div className="mt-3">
                <Part
                  label={i18n_t('interviewPrep', 'partCoverage', { company })}
                  value={`${readiness.parts.coverage.solved}/${readiness.parts.coverage.total}`}
                  weight={readiness.parts.coverage.weight}
                />
                <Part
                  label={i18n_t('interviewPrep', 'partSkills')}
                  value={readiness.parts.skills.score}
                  weight={readiness.parts.skills.weight}
                />
                <Part
                  label={i18n_t('interviewPrep', 'partMock')}
                  value={readiness.parts.mock.taken
                    ? i18n_t('interviewPrep', 'mockScore', { n: readiness.parts.mock.score })
                    : '—'}
                  weight={readiness.parts.mock.weight}
                  note={readiness.parts.mock.taken ? null : i18n_t('interviewPrep', 'mockNotTaken')}
                />
              </div>
            </>
          ) : (
            <p className="text-xs" style={{ color: '#8A8E99' }}>
              {i18n_t('interviewPrep', 'notEnoughEvidence', { n: minEvidenceSolves })}
            </p>
          )}

          {/* ── the plan ── */}
          {status === 'past' && (
            <p className="text-xs mt-4" style={{ color: '#FFB020' }}>
              {i18n_t('interviewPrep', 'statusPast')}
            </p>
          )}
          {status === 'today' && (
            <p className="text-xs mt-4" style={{ color: '#8A8E99' }}>
              {i18n_t('interviewPrep', 'statusToday')}
            </p>
          )}
          {status === 'nothing_left' && (
            <p className="text-xs mt-4" style={{ color: '#8A8E99' }}>
              {i18n_t('interviewPrep', 'statusNothingLeft', { company })}
            </p>
          )}
          {plan?.beyondPlanDays > 0 && (
            <p className="text-xs mt-4" style={{ color: '#8A8E99' }}>
              {i18n_t('interviewPrep', 'statusBeyond', { n: plan.daysRemaining, d: plan.planDays, company })}
            </p>
          )}

          {plan && plan.days.length > 0 && (
            <div className="mt-4">
              <p className="text-xs font-bold" style={{ color: '#F2F0EA' }}>
                {i18n_t('interviewPrep', 'planTitle')}
              </p>
              <div className="mt-2 flex flex-col gap-1.5" data-testid="interview-prep-today">
                {plan.today.length === 0 && (
                  <p className="text-xs" style={{ color: '#8A8E99' }}>
                    {i18n_t('interviewPrep', 'emptyToday')}
                  </p>
                )}
                {plan.today.map((item, i) => (
                  <button
                    key={`${item.kind}-${item.challengeId || item.interviewId}-${i}`}
                    onClick={() => onOpenItem(item)}
                    className="flex items-center justify-between gap-3 px-3 py-2 rounded-lg text-left transition"
                    style={{ background: '#0E0F13', border: '1px solid #2A2E38' }}
                  >
                    <span className="text-xs" style={{ color: '#F2F0EA' }}>
                      {item.title || itemLabel(item)}
                    </span>
                    <span className="text-[11px] flex-shrink-0" style={{ color: '#8A8E99' }}>
                      {item.title ? itemLabel(item) : ''} {item.difficulty || ''} ›
                    </span>
                  </button>
                ))}
              </div>

              {plan.days.length > 1 && (
                <div className="mt-3">
                  <p className="text-[11px]" style={{ color: '#8A8E99' }}>
                    {i18n_t('interviewPrep', 'planRest')}
                  </p>
                  <div className="mt-1.5 flex flex-wrap gap-1.5">
                    {plan.days.slice(1).map(d => (
                      <span
                        key={d.date}
                        title={d.date}
                        className="px-2 py-1 rounded text-[11px] tabular-nums"
                        style={{ background: '#0E0F13', border: '1px solid #2A2E38', color: '#8A8E99' }}
                      >
                        {i18n_t('interviewPrep', 'planDay', { n: d.dayIndex + 1 })} · {d.items.length}
                      </span>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * InterviewStatusStrip — the founder's four fields, one line, every tab
 * (2026-09-18): WHO · WHEN · WHERE I AM · HOW FAR. Rendered by the parent
 * only under the one helper's `status_strip` gate — an interview person with
 * the flag on — under the header and above the tab strip, so it is the first
 * thing they see on every tab, not only the Coach.
 *
 * Renders what `interviewStatusModel` (src/utils/interview-first.js) hands it
 * and nothing else. No modal, no price, no door into locked content: every
 * cell is a button that goes to the Coach tab and the countdown card, where
 * the company picker and the date input live. The WHERE cell always carries
 * its two-word label ("readiness", "check score", "set coverage") so the
 * number is never read as a pass probability — the honesty guard in
 * tests/interview-prep.test.js reads this component and its i18n namespace.
 *
 * DESIGN.md tokens inline (surface #16181F, border #2A2E38, text #F2F0EA,
 * muted #8A8E99). Numbers are Geist Mono, tabular. The accent #FFE34D
 * appears in exactly one place, the WHEN number at ≤ 7 days — a streak-like
 * urgency signal, which DESIGN.md permits. Mobile (< 768px): two rows of two.
 */
function InterviewStatusStrip({ model, onCell }) {
  if (!model) return null;
  const mono = { fontFamily: '"Geist Mono", ui-monospace, SFMono-Regular, Menlo, monospace', fontVariantNumeric: 'tabular-nums' };
  const muted = { color: '#8A8E99' };
  const text = { color: '#F2F0EA' };
  const Cell = ({ id, label, children }) => (
    <button
      type="button"
      data-testid={`interview-status-${id}`}
      onClick={() => onCell && onCell(id)}
      className="flex min-w-0 flex-col gap-0.5 px-3 py-2 text-left transition hover:bg-white/5 md:flex-row md:items-baseline md:gap-2"
      style={{ background: '#16181F' }}
      title={label}
    >
      <span className="text-[10px] uppercase tracking-wide flex-shrink-0" style={muted}>{label}</span>
      <span className="text-xs truncate" style={text}>{children}</span>
    </button>
  );
  const Num = ({ children, accent = false }) => (
    <span style={{ ...mono, color: accent ? '#FFE34D' : '#F2F0EA' }}>{children}</span>
  );
  const Link = ({ children }) => (
    <span className="underline decoration-dotted underline-offset-2" style={muted}>{children}</span>
  );

  const { who, when, where, howFar } = model;
  const whenText = !when.hasDate || when.days === null
    ? <Link>{i18n_t('interviewStatus', 'setDate')}</Link>
    : when.past
      ? <span style={muted}>{i18n_t('interviewStatus', 'datePast')}</span>
      : when.days === 0
        ? <Num accent>{i18n_t('interviewStatus', 'dayToday')}</Num>
        : <Num accent={when.urgent}>{i18n_t(
            'interviewStatus', when.days === 1 ? 'dayOne' : 'days', { n: when.days })}</Num>;

  const whereLabel = where.kind === 'readiness'
    ? i18n_t('interviewStatus', 'whereReadiness')
    : where.kind === 'check'
      ? i18n_t('interviewStatus', 'whereCheck')
      : (where.scoped ? i18n_t('interviewStatus', 'whereCoverage') : i18n_t('interviewStatus', 'whereSolved'));
  const whereText = where.kind === 'coverage'
    ? (where.total
        ? <><Num>{where.solved}</Num> <span style={muted}>{i18n_t('interviewStatus', 'of')}</span> <Num>{where.total}</Num></>
        : <Num>{where.solved}</Num>)
    : <><Num>{where.score}</Num> <span style={muted}>/ 100</span></>;

  const howFarText = !howFar
    ? <span style={muted}>{i18n_t('interviewStatus', 'noPlan')}</span>
    : <>
        <Num>{howFar.today}</Num> <span style={muted}>{i18n_t('interviewStatus', 'today')}</span>
        <span style={muted}> · </span>
        <Num>{howFar.left}</Num> <span style={muted}>{i18n_t('interviewStatus', 'left')}</span>
        {howFar.pro > 0 && (
          <><span style={muted}> · </span><Num>{howFar.pro}</Num> <span style={muted}>{i18n_t('interviewStatus', 'pro')}</span></>
        )}
      </>;

  return (
    <div
      data-testid="interview-status"
      className="mb-3 grid grid-cols-2 md:grid-cols-4 gap-px rounded-lg overflow-hidden"
      // Hairlines between cells in both layouts: a 1px gap over the border
      // colour. Tailwind's divide-* would border the first row's second
      // cell on mobile.
      style={{ background: '#2A2E38', border: '1px solid #2A2E38' }}
    >
      <Cell id="who" label={i18n_t('interviewStatus', 'labelWho')}>
        {who.hasCompany
          ? <span style={text}>{who.company}</span>
          : <Link>{i18n_t('interviewStatus', 'nameCompany')}</Link>}
      </Cell>
      <Cell id="when" label={i18n_t('interviewStatus', 'labelWhen')}>{whenText}</Cell>
      <Cell id="where" label={whereLabel}>{whereText}</Cell>
      <Cell id="howfar" label={i18n_t('interviewStatus', 'labelHowFar')}>{howFarText}</Cell>
    </div>
  );
}

/**
 * RadarPopToast — floating dopamine moment after a correct solve.
 * Pure presentational. Parent supplies pop = { skills, deltas, shownAt } and
 * an onClose callback. Auto-dismiss is owned by the parent (useEffect timer).
 * Shows the archetype + the axes that went up, with yellow pulse rings.
 */
function RadarPopToast({ pop, onClose, onShare, bigTargets = false }) {
  if (!pop) return null;
  const deltaEntries = Object.entries(pop.deltas || {}).filter(([, v]) => v > 0);
  const deltaText = deltaEntries.map(([s, v]) => {
    const meta = RADAR_DEFAULT_META[s] || {};
    return `${meta.short || s} +${v}`;
  }).join(' · ');
  const archetype = deriveArchetype(pop.skills || {});

  return (
    <div
      className="sq-radar-pop fixed bottom-6 right-6 z-50 w-[320px] p-4 rounded-2xl bg-gray-900/95 backdrop-blur border border-yellow-400/30 shadow-2xl"
      style={{ animation: 'radarPopIn 0.4s ease-out' }}
      role="status"
      aria-live="polite"
    >
      <button
        onClick={onClose}
        className={bigTargets
          ? 'absolute top-0 right-0 w-11 h-11 flex items-center justify-center text-gray-500 hover:text-gray-200 text-base rounded-full hover:bg-white/5'
          : 'absolute top-2 right-2 w-6 h-6 flex items-center justify-center text-gray-500 hover:text-gray-200 text-base rounded-full hover:bg-white/5'}
        aria-label="Dismiss"
      >×</button>
      <div className={bigTargets ? 'flex items-center gap-3 mb-2 pr-10' : 'flex items-center gap-3 mb-2 pr-6'}>
        <span className="text-2xl flex-shrink-0">{archetype.emoji}</span>
        <div className="min-w-0">
          <p className="text-sm font-bold text-[#F2F0EA] truncate">{archetype.name}</p>
          {deltaText && (
            <p className="text-[11px] text-yellow-300 font-bold">{deltaText}</p>
          )}
        </div>
      </div>
      <div className="flex justify-center py-1">
        <SkillRadar
          skills={pop.skills}
          size={220}
          highlightDeltas={pop.deltas}
          showLabels={true}
          showScores={false}
        />
      </div>
      <div className="mt-2 flex gap-2">
        <button
          onClick={onClose}
          className={`flex-1 text-xs py-2 rounded-lg bg-gray-800 hover:bg-gray-700 text-gray-300 font-semibold transition${bigTargets ? ' min-h-[44px]' : ''}`}
        >Dismiss</button>
        {onShare && (
          <button
            onClick={onShare}
            className={`flex-1 text-xs py-2 rounded-lg bg-yellow-400/90 hover:bg-yellow-400 text-gray-900 font-bold transition${bigTargets ? ' min-h-[44px]' : ''}`}
          >Share →</button>
        )}
      </div>
    </div>
  );
}


function SkillRadarChart({ skillLevels: rawLevels, size = 340, onPractice, onDrill, highlightDeltas = null, onShare = null, onCopyLink = null, onOpenProfile = null, archetype = null }) {
  // Primitive handles its own key normalization, but we also normalize here so
  // the adjacent skill list + header stats operate on canonical keys.
  const skillLevels = radarNormalizeSkills(rawLevels || {});
  const topics = RADAR_DEFAULT_SKILLS;
  const meta = RADAR_DEFAULT_META;

  const vals = topics.map(t => skillLevels[t] || 0);
  const overall = Math.round(vals.reduce((a, b) => a + b, 0) / vals.length);
  const strong = vals.filter(v => v >= 70).length;
  const moderate = vals.filter(v => v >= 40 && v < 70).length;
  const weak = vals.filter(v => v > 0 && v < 40).length;
  const notStarted = vals.filter(v => v === 0).length;
  
  const tier = overall >= 80 ? { name: 'Master', color: '#a855f7', bg: 'from-purple-500/20 to-pink-500/20' } :
               overall >= 60 ? { name: 'Advanced', color: '#22c55e', bg: 'from-green-500/20 to-emerald-500/20' } :
               overall >= 40 ? { name: 'Intermediate', color: '#eab308', bg: 'from-yellow-500/20 to-orange-500/20' } :
                               { name: 'Beginner', color: '#ef4444', bg: 'from-red-500/20 to-orange-500/20' };
  
  // Sort by value for the bar list (weakest first to highlight areas to work on)
  const sorted = [...topics].sort((a, b) => (skillLevels[a] || 0) - (skillLevels[b] || 0));
  const weakest = sorted[0];

  const getBg = (v) => v >= 70 ? 'bg-green-500' : v >= 40 ? 'bg-yellow-500' : v > 0 ? 'bg-red-500' : 'bg-gray-700';
  const getTx = (v) => v >= 70 ? 'text-green-400' : v >= 40 ? 'text-yellow-400' : v > 0 ? 'text-red-400' : 'text-gray-600';
  
  const derivedArchetype = archetype || deriveArchetype(skillLevels);

  return (
    <div>
      {/* Archetype banner — the identity artifact. Shown above the scores
          because users should see "I'm The Window Wizard" first, then the
          numbers that back it up. */}
      {derivedArchetype && overall > 0 && (
        <div className="mb-4 p-4 rounded-xl bg-gradient-to-r from-purple-600/20 via-pink-500/15 to-purple-600/20 border border-yellow-400/30 flex items-center gap-4 flex-wrap">
          <span className="text-4xl flex-shrink-0">{derivedArchetype.emoji}</span>
          <div className="flex-1 min-w-0">
            <p className="text-[10px] text-yellow-300 font-bold uppercase tracking-widest">{i18n_t('profile', 'yourArchetype')}</p>
            <p className="text-xl font-black text-[#F2F0EA] truncate">
              {derivedArchetype.id ? i18n_t('archetypes', `${derivedArchetype.id}_name`) : derivedArchetype.name}
            </p>
            <p className="text-xs text-gray-400 mt-0.5">
              {derivedArchetype.id
                ? i18n_t('archetypes', derivedArchetype.taglineKey || `${derivedArchetype.id}_tagline`)
                : derivedArchetype.tagline}
            </p>
          </div>
          <div className="flex items-center gap-2 flex-shrink-0">
            {/* Public profile link. Points at /u/:handle — NOT the old
                /app.html?profile= form. Both render the same page, but only
                /u/ goes through api/u.js, which is what writes the per-profile
                og: tags. The query-param URL was the one users could actually
                copy out of the address bar, so every shared profile unfurled
                as the generic site card. */}
            {typeof window !== 'undefined' && window.__currentUser && (
              <a
                href={`/u/${encodeURIComponent(String(window.__currentUser).toLowerCase())}/`}
                target="_blank"
                rel="noopener noreferrer"
                onClick={() => { if (onOpenProfile) onOpenProfile(); }}
                className="px-3 py-2 bg-gray-800/60 hover:bg-gray-700 text-gray-200 font-semibold text-sm rounded-lg transition border border-gray-700"
                title="View your public profile page (opens in new tab)"
              >
                🔗 {i18n_t('profile', 'profileBtn')}
              </a>
            )}
            {/* Copy link is the accent CTA, not the image copy. A pasted PNG
                carries no URL: 8 people had used the image share and not one
                of them could send a reader back here. The link unfurls to the
                same card AND attributes the visit. */}
            {onCopyLink && (
              <button
                onClick={onCopyLink}
                className="px-4 py-2 bg-yellow-400 hover:bg-yellow-300 text-gray-900 font-bold text-sm rounded-lg transition shadow-lg shadow-yellow-400/20"
                title="Copy your profile link — unfurls as your radar card"
              >
                🔗 {i18n_t('profile', 'copyLinkBtn')}
              </button>
            )}
            {onShare && (
              <button
                onClick={onShare}
                className="px-3 py-2 bg-gray-800/60 hover:bg-gray-700 text-gray-200 font-semibold text-sm rounded-lg transition border border-gray-700"
                title="Copy a shareable PNG of your radar to the clipboard"
              >
                📋 {i18n_t('profile', 'shareBtn')}
              </button>
            )}
          </div>
        </div>
      )}

      {/* Header: Overall Ring + Tier + Stats */}
      <div className={`flex items-center gap-5 mb-5 p-4 rounded-xl bg-gradient-to-r ${tier.bg} border border-white/5`}>
        <div className="relative w-[76px] h-[76px] flex-shrink-0">
          <svg viewBox="0 0 80 80" className="w-[76px] h-[76px]">
            <circle cx="40" cy="40" r="34" fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="7" />
            <circle cx="40" cy="40" r="34" fill="none"
              stroke={tier.color} strokeWidth="7" strokeLinecap="round"
              strokeDasharray={`${(overall / 100) * 213.6} 213.6`}
              transform="rotate(-90 40 40)" />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className="text-2xl font-black leading-none" style={{ color: tier.color }}>{overall}</span>
            <span className="text-[9px] text-gray-500 font-medium">/ 100</span>
          </div>
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1.5">
            <span className="text-lg font-bold text-[#F2F0EA]">{i18n_t('profile', 'proficiency')}</span>
            <span className="text-xs font-bold px-2 py-0.5 rounded-full" style={{ background: tier.color + '30', color: tier.color }}>{(() => {
              // Map English tier names from the SkillRadarChart's tier object
              // to localized labels. Falls back to the raw name for unknown tiers.
              const map = {
                'Beginner': 'proficiencyBeginner',
                'Intermediate': 'proficiencyIntermediate',
                'Advanced': 'proficiencyAdvanced',
                'Expert': 'proficiencyExpert',
              };
              const k = map[tier.name];
              return k ? i18n_t('profile', k) : tier.name;
            })()}</span>
          </div>
          <div className="grid grid-cols-4 gap-2">
            <div className="text-center px-2 py-1 rounded-lg bg-black/20">
              <p className="text-base font-bold text-green-400">{strong}</p>
              <p className="text-[9px] text-gray-500 leading-tight">{i18n_t('profile', 'countStrong')}</p>
            </div>
            <div className="text-center px-2 py-1 rounded-lg bg-black/20">
              <p className="text-base font-bold text-yellow-400">{moderate}</p>
              <p className="text-[9px] text-gray-500 leading-tight">{i18n_t('profile', 'countModerate')}</p>
            </div>
            <div className="text-center px-2 py-1 rounded-lg bg-black/20">
              <p className="text-base font-bold text-red-400">{weak}</p>
              <p className="text-[9px] text-gray-500 leading-tight">{i18n_t('profile', 'countWeak')}</p>
            </div>
            <div className="text-center px-2 py-1 rounded-lg bg-black/20">
              <p className="text-base font-bold text-gray-500">{notStarted}</p>
              <p className="text-[9px] text-gray-500 leading-tight">{i18n_t('profile', 'countNew')}</p>
            </div>
          </div>
        </div>
      </div>

      {/* Radar + Skill List */}
      <div className="flex flex-col lg:flex-row gap-5">
        {/* Radar (primitive from src/components/SkillRadar.jsx) */}
        <div className="flex-shrink-0 mx-auto">
          <SkillRadar
            skills={skillLevels}
            size={size}
            canonicalSkills={topics}
            meta={meta}
            highlightDeltas={highlightDeltas}
          />
        </div>

        {/* Skill List (sorted weakest first) */}
        <div className="flex-1 min-w-0">
          <p className="text-xs text-gray-500 font-medium mb-2 uppercase tracking-wider">{i18n_t('practice', 'allSkills')}</p>
          <div className="space-y-1.5">
            {sorted.map(topic => {
              const v = skillLevels[topic] || 0;
              const m = meta[topic];
              return (
                <div key={topic} className="flex items-center gap-2 p-2 rounded-lg bg-gray-800/30 hover:bg-gray-800/60 transition-all group">
                  <span className="text-base w-6 text-center">{m.icon}</span>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-semibold text-gray-200 truncate">{topic}</span>
                      <span className={`text-[10px] font-bold ${getTx(v)}`}>{v > 0 ? `${v}%` : i18n_t('practice', 'newScoreTag')}</span>
                    </div>
                    <div className="h-1 bg-gray-800 rounded-full overflow-hidden mt-0.5">
                      <div className={`h-full rounded-full ${getBg(v)} transition-all duration-700`} style={{ width: `${Math.max(v, 2)}%` }} />
                    </div>
                  </div>
                  {v < 60 && (onDrill || onPractice) && (
                    <div className="flex items-center gap-1 flex-shrink-0">
                      {onDrill && (
                        <button
                          onClick={() => onDrill(topic)}
                          className="text-[10px] px-2 py-1 bg-yellow-500/20 hover:bg-yellow-500/40 text-yellow-300 rounded-md transition-all font-bold border border-yellow-500/40"
                          title={i18n_t('practice', 'fix5Tooltip', { topic })}
                        >
                          {i18n_t('practice', 'fix5')}
                        </button>
                      )}
                      {onPractice && (
                        <button
                          onClick={() => onPractice(topic)}
                          className="opacity-0 group-hover:opacity-100 text-[10px] px-2 py-1 bg-purple-500/30 hover:bg-purple-500/50 text-purple-300 rounded-md transition-all font-medium"
                          title={i18n_t('practice', 'studyWithTutor')}
                        >
                          🤖
                        </button>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>
      
      {/* Recommended Next Action */}
      {onPractice && (skillLevels[weakest] || 0) < 70 && (
        <button
          onClick={() => onPractice(weakest)}
          className="mt-4 w-full p-3 rounded-xl border border-purple-500/30 bg-gradient-to-r from-purple-500/10 to-pink-500/10 hover:from-purple-500/20 hover:to-pink-500/20 transition-all flex items-center gap-3 group"
        >
          <div className="w-9 h-9 rounded-lg bg-purple-500/20 flex items-center justify-center text-lg flex-shrink-0">
            {meta[weakest].icon}
          </div>
          <div className="flex-1 text-left">
            <p className="text-sm font-bold text-purple-300">Recommended: Improve {weakest}</p>
            <p className="text-xs text-gray-500">{meta[weakest].desc} • Currently {(skillLevels[weakest] || 0)}% — tap to learn with AI Tutor</p>
          </div>
          <span className="text-purple-400 text-lg group-hover:translate-x-1 transition-transform">→</span>
        </button>
      )}
    </div>
  );
}


// Tutor message text (src/utils/tutor-render.js): code is never run through
// a markdown rule, headings are drawn, ligatures are off in code so >= is
// not drawn as ≥ (founder QA 2026-09-19, round 3, items 1–3).
function TutorText({ content, codeClassName = 'bg-gray-900 text-green-400 p-2 rounded my-2 overflow-x-auto font-mono text-xs' }) {
  const blocks = parseTutorContent(content);
  const noLig = { fontVariantLigatures: 'none', fontFeatureSettings: '"liga" 0, "calt" 0' };
  const renderParts = (parts) => parts.map((p, k) => (
    p.t === 'code' ? <code key={k} className="font-mono text-[0.95em] px-1 rounded bg-black/40" style={noLig}>{p.v}</code>
      : p.t === 'bold' ? <strong key={k} className="font-bold text-[#F2F0EA]">{p.v}</strong>
      : p.t === 'em' ? <em key={k} className="italic">{p.v}</em>
      : p.t === 'question' ? <span key={k} className="block mt-4 mb-2 text-yellow-400 font-bold text-base">📝 QUESTION:</span>
      : <span key={k}>{p.v}</span>
  ));
  return (
    <div className="text-sm whitespace-pre-wrap" data-testid="tutor-text">
      {blocks.map((b, j) => (
        b.type === 'code' ? <pre key={j} className={codeClassName} style={noLig}>{b.code}</pre>
          : b.type === 'heading' ? <p key={j} className="font-bold text-[#F2F0EA] mt-2 mb-1">{renderParts(b.parts)}</p>
          : <span key={j}>{renderParts(b.parts)}</span>
      ))}
    </div>
  );
}

function ResultsTable({ columns, rows, error, smartError, onTryFix, query }) {
  if (error) {
    return (
      <div className="p-4 bg-red-500/20 border border-red-500/50 rounded-lg">
        <div className="flex items-start gap-2 mb-3">
          <span className="text-red-400 text-lg">❌</span>
          <div>
            <p className="text-red-400 font-medium">{i18n_t('practice', 'resultErrorLabel')}</p>
            <p className="text-red-300 text-sm">{error}</p>
          </div>
        </div>
        
        {smartError && smartError.suggestions && smartError.suggestions.length > 0 && (
          <div className="mt-3 p-3 bg-yellow-500/10 border border-yellow-500/30 rounded-lg">
            <p className="text-yellow-400 font-medium text-sm mb-2">💡 Suggestions:</p>
            <ul className="space-y-1">
              {smartError.suggestions.map((suggestion, i) => (
                <li key={i} className="text-yellow-300 text-sm flex items-start gap-2">
                  <span className="text-yellow-500">•</span>
                  <span>{suggestion}</span>
                </li>
              ))}
            </ul>
            
            {smartError.fixedQuery && onTryFix && (
              <button
                onClick={() => onTryFix(smartError.fixedQuery)}
                className="mt-3 px-4 py-2 bg-green-500/20 border border-green-500/50 rounded-lg text-green-400 text-sm hover:bg-green-500/30 transition-all flex items-center gap-2"
              >
                <span>✨</span>
                Try suggested fix
              </button>
            )}
          </div>
        )}
      </div>
    );
  }
  if (!rows?.length) return <p className="text-gray-400 italic">{i18n_t('practice', 'resultNoResults')}</p>;
  // Per-column decimal precision. Scan each column across all rows to find
  // the max decimal places seen. Whole numbers in that column then display
  // with the same precision, so ROUND(x, 1) always shows "X.Y" even when
  // the underlying value is a whole number. Fixes student confusion.
  const columnDecimals = columnDecimalsFor(columns, rows);
  return (
    <div className="overflow-auto max-h-72">
      <table className="min-w-full text-sm border border-green-500/30">
        <thead className="bg-green-500/20 sticky top-0">
          <tr>{columns.map((c,i) => <th key={i} className="px-3 py-2 text-left font-medium text-green-300 border-b border-green-500/30">{c}</th>)}</tr>
        </thead>
        <tbody>
          {rows.slice(0,100).map((row,i) => (
            <tr key={i} className="hover:bg-green-500/10">
              {row.map((cell,j) => <td key={j} className="px-3 py-2 border-b border-green-500/20 text-gray-300">{cell === null ? <span className="text-gray-500">NULL</span> : formatCell(cell, null, columnDecimals[j])}</td>)}
            </tr>
          ))}
        </tbody>
      </table>
      {rows.length > 100 && <p className="text-xs text-gray-500 mt-2">Showing 100 of {nRows(rows.length)}</p>}
    </div>
  );
}

