      const next = {
        ...existing,
        lessonId: '1',
        firstWeakness: existing.firstWeakness || kind,
        latestWeakness: kind,
        counts: {
          ...counts,
          [kind]: (Number(counts[kind]) || 0) + 1,
        },
        lastExerciseId: exercise.id,
        lastDetail: detail,
        updatedAt: new Date().toISOString(),
      };
      localStorage.setItem(FOUNDATION_WEAKNESS_STORAGE_KEY, JSON.stringify(next));
