  // ============ DAILY LOGIN REWARDS ============
  // Founder QA 2026-09-19, item 8: after login the Pro modal and the reward
  // calendar opened back to back, and a claimed reward came back on every
  // reload. Two guards: the calendar never opens within ten minutes of a Pro
  // modal (it waits for the next visit, nothing is lost), and a per-browser
  // key records the day it was shown or claimed, so a cloud row that has not
  // caught up yet cannot bring it back.
  const proModalShownAtRef = useRef(0);
  useEffect(() => { if (showProModal) proModalShownAtRef.current = Date.now(); }, [showProModal]);
  const rewardSeenKey = (u) => `sqlquest_reward_seen_${u}`;
  
  // Compute current streak and max streak from loginCalendar
  const computeStreaksFromCalendar = (calendar) => {
    const dates = Object.keys(calendar).filter(d => calendar[d]).sort();
    if (dates.length === 0) return { current: 0, max: 0 };

    const today = getTodayString();
    const yesterdayStr = getYesterdayString();
    
    // Calculate all streaks
    let maxStreak = 1;
    let currentRun = 1;
    
    for (let i = 1; i < dates.length; i++) {
      const prev = new Date(dates[i - 1] + 'T12:00:00');
      const curr = new Date(dates[i] + 'T12:00:00');
      const diffDays = Math.round((curr - prev) / (1000 * 60 * 60 * 24));
      
      if (diffDays === 1) {
        currentRun++;
      } else {
        maxStreak = Math.max(maxStreak, currentRun);
        currentRun = 1;
      }
    }
    maxStreak = Math.max(maxStreak, currentRun);
    
    // Calculate current streak (must include today or yesterday)
    const lastDate = dates[dates.length - 1];
    if (lastDate !== today && lastDate !== yesterdayStr) {
      // Last login was more than 1 day ago - current streak is 0 (or 1 if today is being added)
      return { current: 0, max: maxStreak };
    }
    
    // Walk backwards from the most recent date to find current streak
    let currentStreak = 1;
    for (let i = dates.length - 2; i >= 0; i--) {
      const curr = new Date(dates[i + 1] + 'T12:00:00');
      const prev = new Date(dates[i] + 'T12:00:00');
      const diffDays = Math.round((curr - prev) / (1000 * 60 * 60 * 24));
      
      if (diffDays === 1) {
        currentStreak++;
      } else {
        break;
      }
    }
    
    return { current: currentStreak, max: Math.max(maxStreak, currentStreak) };
  };

  const checkDailyLoginReward = () => {
    if (!currentUser || isGuest) return;
    
    const today = getTodayString();
    const userData = JSON.parse(localStorage.getItem(`sqlquest_user_${currentUser}`) || '{}');
    let seenHere = null;
    try { seenHere = localStorage.getItem(rewardSeenKey(currentUser)); } catch (_) {}
    const lastRewardShown = seenHere === today ? today : userData.lastRewardShownDate;
    const lastLoginDate = userData.lastLoginDate;
    
    // Already claimed reward today - don't show popup again
    if (lastLoginDate === today) {
      const calendar = { ...loginCalendar, ...(userData.loginCalendar || {}), [today]: true };
      const streaks = computeStreaksFromCalendar(calendar);
      setLoginStreak(streaks.current);
      setMaxLoginStreak(Math.max(streaks.max, userData.maxLoginStreak || 0));
      setLastLoginDate(today);
      return;
    }
    
    // Already showed reward popup today - just compute streaks for display
    if (lastRewardShown === today) {
      const calendar = { ...loginCalendar, ...(userData.loginCalendar || {}), [today]: true };
      const streaks = computeStreaksFromCalendar(calendar);
      setLoginStreak(streaks.current);
      setMaxLoginStreak(Math.max(streaks.max, userData.maxLoginStreak || 0));
      setLastLoginDate(today);
      return;
    }
    
    // Add today to calendar and compute streaks
    const updatedCalendar = { ...loginCalendar, ...(userData.loginCalendar || {}), [today]: true };
    const streaks = computeStreaksFromCalendar(updatedCalendar);
    const newStreak = streaks.current;
    const newMaxStreak = Math.max(streaks.max, userData.maxLoginStreak || 0);
    
    // Check for comeback_kid achievement (returning after 7+ days)
    if (lastLoginDate && !unlockedAchievements.has('comeback_kid')) {
      const lastDate = new Date(lastLoginDate);
      const todayDate = new Date(today);
      const daysDiff = Math.floor((todayDate - lastDate) / (1000 * 60 * 60 * 24));
      if (daysDiff >= 7) {
        setTimeout(() => unlockAchievement('comeback_kid'), 2000);
      }
    }
    
    // The visit is still recorded — loginCalendar feeds the profile's "Last
    // login" and the perfect_week / monthly_legend achievements — but opening
    // the app is no longer rewarded and nothing pops up over the Learning Path.
    // Until 2026-09-21 this is where the Daily Reward modal opened; the reward
    // now waits for a solved question (claimDailyReward, the streak card).
    userData.lastRewardShownDate = today;
    try { localStorage.setItem(rewardSeenKey(currentUser), today); } catch (_) {}
    userData.loginCalendar = updatedCalendar;
    userData.maxLoginStreak = newMaxStreak;
    userData.lastLoginDate = today;
    saveUserData(currentUser, userData);

    setLoginStreak(newStreak);
    setMaxLoginStreak(newMaxStreak);
    setLastLoginDate(today);
  };
  
  // The one reader of the daily_reward surface: the streak card's XP handout
