  const handleChangePassword = async () => {
    setChangePasswordError('');
    setChangePasswordSuccess('');
    
    // Validate inputs
    if (!currentPassword) {
      setChangePasswordError('Please enter your current password');
      return;
    }
    if (!newPassword) {
      setChangePasswordError('Please enter a new password');
      return;
    }
    if (newPassword.length < 6) {
      setChangePasswordError('New password must be at least 6 characters');
      return;
    }
    if (newPassword !== confirmPassword) {
      setChangePasswordError('New passwords do not match');
      return;
    }
    if (currentPassword === newPassword) {
      setChangePasswordError('New password must be different from current password');
      return;
    }
    
    // Check password strength
    const strength = getPasswordStrength(newPassword);
    if (strength.score < 3) {
      setChangePasswordError('Please choose a stronger password');
      return;
    }
    
    try {
      // Server-side (2026-09-13): account-password checks the current password
      // and writes the new one; client saves can no longer replace a hash.
      if (isSupabaseConfigured()) {
        const res = await callAccountFunction('account-password', { username: currentUser, currentPassword, newPassword });
        if (res.status === 'ok') {
          try {
            const local = JSON.parse(localStorage.getItem(`sqlquest_user_${currentUser}`) || '{}');
            local.salt = res.salt;
            local.passwordHash = res.passwordHash;
            localStorage.setItem(`sqlquest_user_${currentUser}`, JSON.stringify(local));
          } catch (_) {}
          // Session tokens (2026-09-23): the change ended every session this
          // account had, including this one; keep the fresh one it returned.
          if (res.sessionToken) { try { writeSessionToken(localStorage, currentUser, res.sessionToken); } catch (_) {} }
          setCurrentPassword('');
          setNewPassword('');
          setConfirmPassword('');
          setChangePasswordSuccess('Password changed successfully!');
          setTimeout(() => { setChangePasswordSuccess(''); setShowChangePassword(false); }, 2000);
          return;
        }
        if (res.status === 'invalid') { setChangePasswordError('Current password is incorrect'); return; }
        if (res.status === 'locked') { setChangePasswordError('Too many attempts. Please wait 15 minutes and try again.'); return; }
        // unavailable: fall through to the old in-browser path
      }

      // Verify current password
      const userData = await loadUserData(currentUser, true, { legacyTable: true });
      if (!userData) {
        setChangePasswordError('User data not found');
        return;
      }
      
      const isValid = await verifyPassword(currentPassword, userData.salt, userData.passwordHash);
      if (!isValid) {
        setChangePasswordError('Current password is incorrect');
        return;
      }
      
      // Generate new hash
      const newSalt = generateSalt();
      const newHash = await hashPassword(newPassword, newSalt);

      // Update user data
      userData.salt = newSalt;
      userData.passwordHash = newHash;
      // force: true → cloud write completes BEFORE we tell the user it worked.
      // Without this the success modal could close while the actual Supabase
      // write was still queued behind a 5s debounce — and a navigation/logout
      // inside that window would silently lose the change. (Murat 2026-05-07.)
      await saveUserData(currentUser, userData, { force: true });

      // Clear form and show success
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
      setChangePasswordSuccess('Password changed successfully!');

      // Hide success after 3 seconds
      setTimeout(() => {
        setChangePasswordSuccess('');
        setShowChangePassword(false);
      }, 2000);
    } catch (err) {
      console.error('Error changing password:', err);
      // Distinguish cloud-sync errors from generic ones — they need a retry,
      // not just a vague "try again".
      if (err && typeof err.message === 'string' && err.message.startsWith('Cloud sync failed')) {
        setChangePasswordError('Could not save the new password to the cloud. Please check your connection and try again.');
      } else {
        setChangePasswordError('An error occurred. Please try again.');
      }
    }
  };

