        headers: {
          'Content-Type': 'application/json',
          apikey: window.SUPABASE_ANON_KEY,
          Authorization: `Bearer ${window.SUPABASE_ANON_KEY}`,
        },
        body: JSON.stringify({ admin_password: pwd, since_days: referralsSinceDays }),
